#!/usr/bin/env bun
/**
 * Generate src/commands/ui/embedded-ui.ts from the files in src/assets/ui, so
 * adding, removing or renaming a UI file never needs a hand-merged import map.
 *
 * Usage: bun scripts/gen-embedded-ui.ts
 *
 * tests/integration/ui/ui-client.test.ts fails when the generated file is stale.
 */
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(import.meta.dirname, "..");
const ASSETS_DIR = path.join(ROOT, "src/assets/ui");
const OUTPUT_PATH = path.join(ROOT, "src/commands/ui/embedded-ui.ts");
const EMBEDDED_EXTENSIONS = new Set([".html", ".js", ".css"]);

const HEADER = `// This Source Code Form is subject to the terms of the Mozilla Public
// License, v. 2.0. If a copy of the MPL was not distributed with this
// file, You can obtain one at https://mozilla.org/MPL/2.0/.

// GENERATED by scripts/gen-embedded-ui.ts from src/assets/ui. Do not edit;
// run \`bun scripts/gen-embedded-ui.ts\` after adding, removing or renaming a UI file.

`;

/** "chart-view.js" -> "chartViewJs": a unique identifier per file name. */
function importName(file: string): string {
  const { name, ext } = path.parse(file);
  return `${name}-${ext.slice(1)}`.replace(/[-.](\w)/g, (_, c: string) => c.toUpperCase());
}

function renderEmbeddedUi(files: string[]): string {
  const imports = files.map((f) => `import ${importName(f)} from "../../assets/ui/${f}" with { type: "text" };`);
  const entries = files.map((f) => `  "${f}": ${importName(f)} as unknown as string,`);
  return `${HEADER}${imports.join("\n")}\n\nexport const EMBEDDED_UI: Record<string, string> = {\n${entries.join("\n")}\n};\n`;
}

/** Biome sorts imports by path without the extension; match it so the generated file is already formatted. Ties on the stem fall back to the full name. */
function compareByStem(a: string, b: string): number {
  const stem = (file: string) => path.parse(file).name;
  const [sa, sb] = [stem(a), stem(b)];
  if (sa !== sb) return sa < sb ? -1 : 1;
  // Same stem (styles.css / styles.js): break the tie on the full name so the order never depends on readdir.
  return a < b ? -1 : a > b ? 1 : 0;
}

function listUiFiles(): string[] {
  return fs
    .readdirSync(ASSETS_DIR)
    .filter((f) => EMBEDDED_EXTENSIONS.has(path.extname(f)))
    .sort(compareByStem);
}

if (import.meta.main) {
  fs.writeFileSync(OUTPUT_PATH, renderEmbeddedUi(listUiFiles()));
}
